void heapSort(int arr[], int size) {
    // Create a max heap and then extract elements
    // First, build a max heap
    for (int i = size / 2 - 1; i >= 0; i--) {
        // Call heapify on each non-leaf node, starting from the last non-leaf node
        int largest = i;
        int left = 2 * i + 1;
        int right = 2 * i + 2;

        // Heapify down from this node
        if (left < size && arr[left] > arr[largest])
            largest = left;
        if (right < size && arr[right] > arr[largest])
            largest = right;

        if (largest != i) {
            std::swap(arr[i], arr[largest]);
            // Recursively heapify the affected sub-tree
            int parent = i;
            int child = 2 * largest + 1;
            if (child < size && arr[child] > arr[child + 1] && child + 1 < size) {
                // Swap if needed based on heap property
                std::swap(arr[child], arr[child + 1]);
            }
        }
    }

    // Extract elements from the heap one by one
    for (int i = size - 1; i > 0; i--) {
        std::swap(arr[0], arr[i]);
        // Heapify the reduced heap
        int parent = 0;
        int left = 2 * parent + 1;
        int right = 2 * parent + 2;
        if (left < i && arr[left] > arr[parent])
            parent = left;
        if (right < i && arr[right] > arr[parent])
            parent = right;
        if (parent != 0) {
            std::swap(arr[0], arr[parent]);
        }
    }
}

void heapify(int arr[], int n, int i) {
    int largest = i; // Initialize largest as root
    int left = 2 * i + 1; // left = 2*i + 1 and right = 2*i + 2
    int right = 2 * i + 2;

    // If left child is larger than root
    if (left < n && arr[left] > arr[largest])
        largest = left;

    // If right child is larger than largest so far
    if (right < n && arr[right] > arr[largest])
        largest = right;

    // If largest is not root
    if (largest != i) {
        std::swap(arr[i], arr[largest]);
        // Recursively heapify the affected sub-tree
        heapify(arr, n, i);
    }
}

void heapSort(int arr[], int size) {
    // Build heap (rearrange array)
    for (int i = size / 2 - 1; i >= 0; i--) {
        heapify(arr, size, i);
    }

    // One by one extract an element from heap
    for (int i = size - 1; i > 0; i--) {
        // Move current root to end
        std::swap(arr[0], arr[i]);

        // call max heapify on the reduced heap
        heapify(arr, i, 0);
    }
}

